mapper.sql:
FROM knowledge_chunk c JOIN knowledge_document d ON d.id = c.document_id AND d.version = c.version

    AND d.doc_type = #{filters.type}
    AND d.status = #{filters.status}
    AND c.embedding_status = #{filters.embedding}

        AND (d.doc_no LIKE #{filters.pattern} ESCAPE '!' OR d.title LIKE #{filters.pattern} ESCAPE '!'
            OR c.heading LIKE #{filters.pattern} ESCAPE '!' OR c.content LIKE #{filters.pattern} ESCAPE '!')

mapper.select:
SELECT c.id, c.chunk_no, c.heading, c.content, c.char_count, c.embedding_status, c.index_error, c.indexed_at,
       d.doc_no, d.title, d.version, d.doc_type, d.source, d.status

ORDER BY d.doc_no, d.version DESC, c.chunk_no LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE knowledge_chunk c JOIN knowledge_document d ON d.id = c.document_id AND d.version = c.version
SET c.embedding_status = #{status}, c.indexed_at = #{indexedAt,jdbcType=TIMESTAMP}, c.index_error = #{error,jdbcType=VARCHAR}
WHERE c.id = #{chunkId} AND d.status = 'PUBLISHED'

UPDATE knowledge_chunk
SET embedding_status = 'INDEXED', index_error = NULL, indexed_at = #{indexedAt}
WHERE id IN

    #{id}
